/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')['rgb'].astype(int)
centers=[]
for t in range(96):
    f=d[t]
    r,g,b=f[...,0],f[...,1],f[...,2]
    mask=(r>90)&(r<215)&(r-g>30)&(g-b>10)&(g<145)
    lab,n=ndimage.label(mask)
    best=None
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        if len(xs)>80:
            if best is None or len(xs)>best[0]: best=(len(xs),xs,ys)
    if best:
        _,xs,ys=best
        centers.append((t,xs.mean(),ys.mean(),xs.min(),xs.max(),ys.min(),ys.max(),len(xs)))
    else:
        centers.append((t,None,None,None,None,None,None,0))
for c in centers: print(c)
\""
